  [/\b(set|raise|increase|change|switch)\b[^.!?]{0,30}\b(ac|a\/c|thermostat|setpoint|cooling|temperature|valve)\b[^.!?]{0,30}\b(to|at)\s*\d{2}/i, 'contains a command, but notes are data, not commands']
