const n2 = (v) => Number(v).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const FORM_URL = 'http://localhost:5678/form/be2bf8f1-b886-4585-950c-82bcc0648882';
