function outcome(d) {
  const G = d.guard || {};
  if (d.special === 'RESET') return { tone: 'ok', head: 'Demo memory cleared: devices reopened, history and undo stack emptied' };
  if (d.gate === 'REJECT') return { tone: 'bad', head: G.rule === 'injection_blocked' ? 'Rejected before any AI saw it: prompt injection in the note' : 'Rejected: ' + String(G.rule || '').replace(/_/g, ' ') };
  if (G.status === 'BLOCKED') return { tone: 'bad', head: 'Blocked by a hard rule: ' + String(G.rule).replace(/_/g, ' ') };
  if (G.status === 'NO_CHANGE') return { tone: 'ok', head: 'No change needed: already in that state, nobody asked again' };
  if (d.review && d.review.approved && d.write && d.write.ok) return { tone: 'ok', head: 'Approved by ' + d.review.reviewer + ' and ' + (d.request.type === 'ROLLBACK' ? 'rolled back' : 'applied') + ': ' + reqText(d.request) };
