// ---------- guard 1: privacy filter (allow-list, not block-list) ----------
const ALLOWED_OUT = ['scenario_id', 'scenario_name', 'leak_verdict', 'est_leak_lph', 'est_leak_litres_per_day', 'leak_bill_impact_aed', 'bill_total_aed', 'water_cost_aed', 'electricity_cost_aed', 'elec_slabs_used', 'water_gallons', 'electricity_kwh', 'tariff_verified', 'guard_rule', 'guard_status', 'guard_reason', 'request_type', 'requested_setpoint_c', 'outdoor_c', 'task', 'steps_used', 'tools_done', 'runnable', 'data_ok', 'open_alert', 'earlier_decision'];
